from collections.abc import Sequence

Log = tuple[int, str]

def lower_bound(logs: Sequence[Log], target: int) -> int:
    left, right = 0, len(logs)
    while left < right:
        mid = (left + right) // 2
        if logs[mid][0] < target:
            left = mid + 1
        else:
            right = mid
    return left

def upper_bound(logs: Sequence[Log], target: int) -> int:
    left, right = 0, len(logs)
    while left < right:
        mid = (left + right) // 2
        if logs[mid][0] <= target:
            left = mid + 1
        else:
            right = mid
    return left

def logs_in_range(logs: Sequence[Log], start: int, end: int) -> list[Log]:
    if start > end:
        raise ValueError("start must be <= end")
    return list(logs[lower_bound(logs, start):upper_bound(logs, end)])

